def rank(name, **_extra):
    import json, os, datetime, time, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0398000" if __import__("os").path.isdir("./environment_mix/0398000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(6).hex()}"

    def _minute_bucket(dt):
        dt = dt.replace(second=0, microsecond=0)
        return dt.isoformat() + "Z"

    def _record_usage(workspace_id, status):
        counters = _load("workspace_usage_counters.json")
        wstart = _minute_bucket(datetime.datetime.utcnow())
        row = None
        for r in counters:
            if r.get("workspace_id") == workspace_id and r.get("window_start") == wstart and r.get("window_seconds") == 60:
                row = r
                break
        if row is None:
            row = {
                "id": _new_id("wuc"),
                "workspace_id": workspace_id,
                "window_start": wstart,
                "window_seconds": 60,
                "ops_requested": 0,
                "ops_succeeded": 0,
                "ops_failed": 0,
                "tensor_bytes_written": 0,
                "created_at": now,
                "updated_at": now,
            }
            counters.append(row)
        row["ops_requested"] = int(row.get("ops_requested") or 0) + 1
        if status == "succeeded":
            row["ops_succeeded"] = int(row.get("ops_succeeded") or 0) + 1
        elif status == "failed":
            row["ops_failed"] = int(row.get("ops_failed") or 0) + 1
        row["updated_at"] = now
        _save("workspace_usage_counters.json", counters)

    def _check_rate_limit(workspace):
        limit = int(workspace.get("ops_per_minute_limit") or 0)
        if limit == 0:
            return None
        counters = _load("workspace_usage_counters.json")
        wstart = _minute_bucket(datetime.datetime.utcnow())
        current = 0
        for r in counters:
            if r.get("workspace_id") == workspace.get("id") and r.get("window_start") == wstart and r.get("window_seconds") == 60:
                try:
                    current = int(r.get("ops_requested") or 0)
                except Exception:
                    current = 0
                break
        if current + 1 > limit:
            return _err("RATE_LIMIT", "Workspace rate limit exceeded.", limit=limit, window_seconds=60)
        return None

    def _op_append(op):
        ops = _load("operations.json")
        ops.append(op)
        _save("operations.json", ops)

    def _op_update(op_id, **fields):
        ops = _load("operations.json")
        for r in ops:
            if r.get("id") == op_id:
                r.update(fields)
                r["updated_at"] = now
                _save("operations.json", ops)
                return r
        return None

    def _transition_ok(current, target):
        graph = {
            "queued": {"running", "cancelled"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set(),
        }
        return target in graph.get(current, set())

    def _matrix_rank(mat):
        # Row-reduction (RREF-ish) with tolerance
        a = [row[:] for row in mat]
        m = len(a)
        n = len(a[0]) if m else 0
        eps = 1e-10
        rank_ = 0
        row = 0
        for col in range(n):
            pivot = None
            maxv = eps
            for r in range(row, m):
                v = abs(a[r][col])
                if v > maxv:
                    maxv = v
                    pivot = r
            if pivot is None:
                continue
            a[row], a[pivot] = a[pivot], a[row]
            piv = a[row][col]
            for c in range(col, n):
                a[row][c] /= piv
            for r in range(m):
                if r != row:
                    factor = a[r][col]
                    if abs(factor) > eps:
                        for c in range(col, n):
                            a[r][c] -= factor * a[row][c]
            rank_ += 1
            row += 1
            if row == m:
                break
        return rank_

    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "Parameter 'name' must be a non-empty string.")
    name = name.strip()

    workspaces = _load("workspaces.json")
    tensors = _load("tensors.json")

    candidate_ws_ids = []
    for t in tensors:
        if t.get("status") == "active" and t.get("name") == name:
            candidate_ws_ids.append(t.get("workspace_id"))
    candidate_ws_ids = [w for w in candidate_ws_ids if isinstance(w, str)]

    workspace = None
    tensor = None
    for ws_id in candidate_ws_ids:
        ws = next((w for w in workspaces if w.get("id") == ws_id), None)
        if ws and ws.get("status") == "active":
            tt = next((t for t in tensors if t.get("workspace_id") == ws_id and t.get("name") == name and t.get("status") == "active"), None)
            if tt:
                workspace, tensor = ws, tt
                break

    if workspace is None or tensor is None:
        any_active_ws = any(w.get("status") == "active" for w in workspaces)
        if not any_active_ws:
            return _err("UNAUTHORIZED", "No active workspace available for this request.")
        return _err("NOT_FOUND", "Tensor not found.")

    rl = _check_rate_limit(workspace)
    if rl:
        return rl

    op_id = _new_id("op")
    op = {
        "id": op_id,
        "workspace_id": workspace["id"],
        "tool_name": "rank",
        "status": "queued",
        "requested_at": now,
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "name": name,
        "name_a": None,
        "name_b": None,
        "shape": None,
        "values": None,
        "scale_factor": None,
        "in_place": None,
        "new_basis": None,
        "new_vector": None,
        "f_str": None,
        "expr_str": None,
        "point": None,
        "is_vector": None,
        "u": None,
        "unit": None,
        "bounds_raw": None,
        "n": None,
        "xlim": None,
        "ylim": None,
        "grid_raw": None,
        "output_kind": "none",
        "result_tensor_id": None,
        "result_payload": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    _op_append(op)
    _record_usage(workspace["id"], status="")  # ops_requested only

    started = datetime.datetime.utcnow().replace(microsecond=0)
    started_at = started.isoformat() + "Z"
    if not _transition_ok("queued", "running"):
        _op_update(op_id, status="failed", started_at=started_at, finished_at=started_at, duration_ms=0, output_kind="none",
                   error_message="Invalid status transition queued->running.")
        _record_usage(workspace["id"], status="failed")
        return _err("INVALID_TRANSITION", "Invalid status transition queued->running.")
    _op_update(op_id, status="running", started_at=started_at)

    refs = _load("operation_tensor_refs.json")
    refs.append({
        "id": _new_id("otr"),
        "operation_id": op_id,
        "tensor_id": tensor["id"],
        "role": "input",
        "created_at": now,
        "updated_at": now,
    })
    _save("operation_tensor_refs.json", refs)

    try:
        shape = tensor.get("shape")
        values = tensor.get("values")
        if not (isinstance(shape, list) and all(isinstance(d, int) for d in shape) and len(shape) >= 1):
            raise ValueError("Stored tensor shape is invalid.")
        if not isinstance(values, list):
            raise ValueError("Stored tensor values are invalid.")
        if len(shape) == 1:
            n = shape[0]
            if n < 1 or len(values) != n:
                raise ValueError("Stored vector values length does not match shape.")
            vec = []
            for v in values:
                if not isinstance(v, (int, float)) or (isinstance(v, float) and (math.isnan(v) or math.isinf(v))):
                    raise ValueError("Vector contains non-finite numeric values.")
                vec.append(float(v))
            eps = 1e-12
            rnk = 0 if all(abs(v) < eps for v in vec) else 1
        elif len(shape) == 2:
            r, c = shape
            if r < 1 or c < 1 or len(values) != r * c:
                raise ValueError("Stored matrix values length does not match shape.")
            mat = []
            idx = 0
            for i in range(r):
                row = []
                for j in range(c):
                    v = values[idx]
                    if not isinstance(v, (int, float)) or (isinstance(v, float) and (math.isnan(v) or math.isinf(v))):
                        raise ValueError("Matrix contains non-finite numeric values.")
                    row.append(float(v))
                    idx += 1
                mat.append(row)
            rnk = int(_matrix_rank(mat))
        else:
            # No higher-order tensor rank notion supported here
            raise ValueError("Rank computation supports only rank-1 (vector) or rank-2 (matrix) tensors.")
    except ValueError as e:
        finished = datetime.datetime.utcnow().replace(microsecond=0)
        finished_at = finished.isoformat() + "Z"
        dur = int(max(0, (finished - started).total_seconds() * 1000))
        if not _transition_ok("running", "failed"):
            _op_update(op_id, status="failed", finished_at=finished_at, duration_ms=dur, output_kind="none",
                       error_message="Invalid status transition running->failed.")
            _record_usage(workspace["id"], status="failed")
            return _err("INVALID_TRANSITION", "Invalid status transition running->failed.")
        _op_update(op_id, status="failed", finished_at=finished_at, duration_ms=dur, output_kind="none", error_message=str(e))
        _record_usage(workspace["id"], status="failed")
        return _err("VALIDATION_ERROR", str(e))

    finished = datetime.datetime.utcnow().replace(microsecond=0)
    finished_at = finished.isoformat() + "Z"
    dur = int(max(0, (finished - started).total_seconds() * 1000))
    if not _transition_ok("running", "succeeded"):
        _op_update(op_id, status="failed", finished_at=finished_at, duration_ms=dur, output_kind="none",
                   error_message="Invalid status transition running->succeeded.")
        _record_usage(workspace["id"], status="failed")
        return _err("INVALID_TRANSITION", "Invalid status transition running->succeeded.")
    _op_update(op_id, status="succeeded", finished_at=finished_at, duration_ms=dur, output_kind="scalar",
               result_tensor_id=None, result_payload={"rank": rnk})
    _record_usage(workspace["id"], status="succeeded")

    return {
        "operation": {"id": op_id, "status": "succeeded", "tool_name": "rank", "workspace_id": workspace["id"]},
        "result": rnk,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)},
    }

def find_orthonormal_basis(name, **_extra):
    import json, os, datetime, time, secrets, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0398000" if __import__("os").path.isdir("./environment_mix/0398000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_dt.isoformat().replace("+00:00", "Z")

    def _minute_bucket_iso(dt):
        dt = dt.astimezone(datetime.timezone.utc).replace(second=0, microsecond=0)
        return dt.isoformat().replace("+00:00", "Z")

    def _new_id(prefix, rows, fixed_prefix=None):
        existing = {r.get("id") for r in rows if isinstance(r, dict) and isinstance(r.get("id"), str)}
        pref = fixed_prefix or prefix
        for _ in range(10_000):
            cid = f"{pref}_{secrets.token_hex(12)}"
            if cid not in existing:
                return cid
        return f"{pref}_{secrets.token_hex(16)}"

    def _ensure_counter_row(counters, ws_id, bucket_iso):
        for i, r in enumerate(counters):
            if isinstance(r, dict) and r.get("workspace_id") == ws_id and r.get("window_start") == bucket_iso and int(r.get("window_seconds", 0) or 0) == 60:
                return i
        counters.append({
            "id": _new_id("sci_wuc", counters, fixed_prefix="sci_wuc"),
            "workspace_id": ws_id,
            "window_start": bucket_iso,
            "window_seconds": 60,
            "ops_requested": 0,
            "ops_succeeded": 0,
            "ops_failed": 0,
            "tensor_bytes_written": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        return len(counters) - 1

    def _start_op(ws, ops, counters):
        bucket_iso = _minute_bucket_iso(now_dt)
        idx = _ensure_counter_row(counters, ws["id"], bucket_iso)
        row = counters[idx]
        limit = int(ws.get("ops_per_minute_limit") or 0)
        proposed = int(row.get("ops_requested") or 0) + 1
        if limit != 0 and proposed > limit:
            return None, _err("RATE_LIMIT", "Workspace rate limit exceeded.", ops_per_minute_limit=limit, window_start=bucket_iso, ops_requested=proposed)
        row["ops_requested"] = proposed
        row["updated_at"] = now_iso

        op = {
            "id": _new_id("sci_op", ops, fixed_prefix="sci_op"),
            "workspace_id": ws["id"],
            "tool_name": "find_orthonormal_basis",
            "status": "queued",
            "requested_at": now_iso,
            "started_at": None,
            "finished_at": None,
            "duration_ms": None,
            "name": name,
            "name_a": None,
            "name_b": None,
            "shape": None,
            "values": None,
            "scale_factor": None,
            "in_place": None,
            "new_basis": None,
            "new_vector": None,
            "f_str": None,
            "expr_str": None,
            "point": None,
            "is_vector": None,
            "u": None,
            "unit": None,
            "bounds_raw": None,
            "n": None,
            "xlim": None,
            "ylim": None,
            "grid_raw": None,
            "output_kind": "none",
            "result_tensor_id": None,
            "result_payload": None,
            "error_message": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        ops.append(op)
        return op, None

    def _transition(op, to):
        g = {"queued": {"running", "cancelled"}, "running": {"succeeded", "failed", "cancelled"}, "succeeded": set(), "failed": set(), "cancelled": set()}
        cur = op.get("status")
        if cur not in g or to not in g[cur]:
            return False
        op["status"] = to
        op["updated_at"] = now_iso
        return True

    def _finish(op, status, counters, ws_id, error_message=None, result_payload=None):
        bucket_iso = _minute_bucket_iso(now_dt)
        idx = _ensure_counter_row(counters, ws_id, bucket_iso)
        if status == "succeeded":
            counters[idx]["ops_succeeded"] = int(counters[idx].get("ops_succeeded") or 0) + 1
        elif status == "failed":
            counters[idx]["ops_failed"] = int(counters[idx].get("ops_failed") or 0) + 1
        counters[idx]["updated_at"] = now_iso

        op["finished_at"] = now_iso
        op["duration_ms"] = int(round((time.time() - t0) * 1000))
        op["output_kind"] = "json" if status == "succeeded" else "none"
        op["result_payload"] = result_payload
        op["error_message"] = error_message
        op["updated_at"] = now_iso

    def _mat_from_tensor_allow_vector(t):
        # Allow 1D vectors too (treated as Nx1 matrix) to avoid overly-strict rejection.
        sh = t.get("shape")
        vals = t.get("values")
        if not (isinstance(sh, list) and len(sh) in (1, 2) and all(isinstance(x, int) for x in sh)):
            return None, _err("VALIDATION_ERROR", "Tensor shape must be 1D or 2D to find an orthonormal basis.", field="shape", shape=sh)
        if len(sh) == 1:
            m, n = sh[0], 1
        else:
            m, n = sh
        if m < 1 or n < 1:
            return None, _err("VALIDATION_ERROR", "Invalid matrix shape.", field="shape", shape=sh)
        if not (isinstance(vals, list) and len(vals) == m * n):
            return None, _err("VALIDATION_ERROR", "Tensor values length does not match shape.", field="values")
        A = []
        k = 0
        for i in range(m):
            row = []
            for j in range(n):
                v = vals[k]; k += 1
                if not isinstance(v, (int, float)) or (isinstance(v, float) and (math.isnan(v) or math.isinf(v))):
                    return None, _err("VALIDATION_ERROR", "Tensor contains non-finite numeric value.", field="values")
                row.append(float(v))
            A.append(row)
        return A, None

    def _dot(u, v): return sum(ui * vi for ui, vi in zip(u, v))
    def _norm(u): return math.sqrt(max(0.0, _dot(u, u)))
    def _scale(u, s): return [ui * s for ui in u]
    def _sub(u, v, a=1.0): return [ui - a * vi for ui, vi in zip(u, v)]

    def _qr_gram_schmidt_cols(A):
        m = len(A)
        n = len(A[0]) if m else 0
        cols = [[A[i][j] for i in range(m)] for j in range(n)]
        Qcols = []
        eps = 1e-12
        for j in range(n):
            v = cols[j][:]
            for q in Qcols:
                proj = _dot(q, v)
                v = _sub(v, q, a=proj)
            nv = _norm(v)
            if nv > eps:
                Qcols.append(_scale(v, 1.0 / nv))
        return Qcols

    if not (isinstance(name, str) and name.strip()):
        return _err("VALIDATION_ERROR", "Invalid 'name'.", field="name")

    workspaces = _load("workspaces.json")
    tensors = _load("tensors.json")
    operations = _load("operations.json")
    oprefs = _load("operation_tensor_refs.json")
    counters = _load("workspace_usage_counters.json")

    ws = tensor = None
    for w in workspaces:
        if not isinstance(w, dict) or w.get("status") != "active":
            continue
        if not isinstance(w.get("id"), str) or not w["id"]:
            continue
        if not isinstance(w.get("ops_per_minute_limit"), int) or w["ops_per_minute_limit"] < 0:
            continue
        ws_id = w["id"]
        t = next((tr for tr in tensors if isinstance(tr, dict) and tr.get("workspace_id") == ws_id and tr.get("status") == "active" and tr.get("name") == name), None)
        if t:
            ws, tensor = w, t
            break
    if not ws:
        return _err("NOT_FOUND", "Tensor not found (must be active).", name=name)

    op, err = _start_op(ws, operations, counters)
    if err:
        _save("workspace_usage_counters.json", counters)
        return err

    if not _transition(op, "running"):
        _save("operations.json", operations)
        _save("workspace_usage_counters.json", counters)
        return _err("INVALID_TRANSITION", "Illegal operation status transition.", operation_id=op["id"], to_status="running")
    op["started_at"] = now_iso

    A, aerr = _mat_from_tensor_allow_vector(tensor)
    if aerr:
        _finish(op, "failed", counters, ws["id"], error_message=aerr["error"]["message"])
        _transition(op, "failed")
        _save("operations.json", operations)
        _save("workspace_usage_counters.json", counters)
        return aerr

    Qcols = _qr_gram_schmidt_cols(A)
    basis = [col for col in Qcols]  # list of vectors
    result_payload = {"basis": basis, "basis_count": len(basis)}

    _finish(op, "succeeded", counters, ws["id"], result_payload=result_payload)
    if not _transition(op, "succeeded"):
        _save("operations.json", operations)
        _save("workspace_usage_counters.json", counters)
        return _err("INVALID_TRANSITION", "Illegal operation status transition.", operation_id=op["id"], to_status="succeeded")

    oprefs.append({"id": _new_id("sci_optr", oprefs, fixed_prefix="sci_optr"), "operation_id": op["id"], "tensor_id": tensor["id"], "role": "input", "created_at": now_iso, "updated_at": now_iso})
    _save("operation_tensor_refs.json", oprefs)
    _save("operations.json", operations)
    _save("workspace_usage_counters.json", counters)

    return {"basis": basis, "operation": {"id": op["id"], "status": op["status"], "output_kind": op["output_kind"]}}

def plot_vector_field(f_str, bounds=None, n=None, **_extra):
    import json, os, datetime, time, ast, math, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0398000" if __import__("os").path.isdir("./environment_mix/0398000") else "/app/database")

    def _load(nm):
        try:
            with open(os.path.join(_DB, nm), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(nm, d):
        with open(os.path.join(_DB, nm), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(ts):
        if not isinstance(ts, str) or not ts:
            return None
        try:
            if ts.endswith("Z"):
                ts2 = ts[:-1]
                return datetime.datetime.fromisoformat(ts2)
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    def _minute_bucket_start(dt):
        return dt.replace(second=0, microsecond=0)

    def _get_or_init_counter(counters, workspace_id, bucket_start, window_seconds=60):
        ws = bucket_start.replace(microsecond=0).isoformat() + "Z"
        for r in counters:
            if r.get("workspace_id") == workspace_id and r.get("window_start") == ws and int(r.get("window_seconds", 0) or 0) == window_seconds:
                return r
        row = {
            "id": _gen_id("wuc"),
            "workspace_id": workspace_id,
            "window_start": ws,
            "window_seconds": window_seconds,
            "ops_requested": 0,
            "ops_succeeded": 0,
            "ops_failed": 0,
            "tensor_bytes_written": 0,
            "created_at": _now(),
            "updated_at": _now(),
        }
        counters.append(row)
        return row

    def _select_authorized_workspace():
        workspaces = _load("workspaces.json")
        for w in workspaces:
            if w.get("status") == "active":
                return w
        return None

    def _validate_vector_expr(expr):
        # Expect 3 components: either "[a,b,c]" / "(a,b,c)" / "a,b,c"
        s = expr.strip()
        if not s:
            return (False, "f_str must be a non-empty string")
        try:
            if (s[0] in "[(" and s[-1] in "])"):
                parsed = ast.literal_eval(s)
                if isinstance(parsed, (list, tuple)) and len(parsed) == 3:
                    comps = list(parsed)
                else:
                    return (False, "f_str must be a 3-component vector expression")
            else:
                parts = [p.strip() for p in s.split(",")]
                if len(parts) != 3:
                    return (False, "f_str must be a 3-component vector expression")
                comps = parts
        except Exception:
            # If literal eval fails, accept comma-separated raw pieces only if 3 parts
            parts = [p.strip() for p in s.split(",")]
            if len(parts) != 3:
                return (False, "f_str must be a 3-component vector expression")
            comps = parts

        # Light parse check: each component should compile as expression
        for c in comps:
            if isinstance(c, (int, float)):
                continue
            if not isinstance(c, str) or not c.strip():
                return (False, "Each component in f_str must be a valid expression")
            try:
                ast.parse(c, mode="eval")
            except Exception:
                return (False, "f_str contains an invalid component expression")
        return (True, comps)

    t0 = time.time()
    op_id = None
    workspace = _select_authorized_workspace()
    if not workspace:
        return _err("UNAUTHORIZED", "No active workspace is available for this operation")

    # Create operation row as queued
    now = _now()
    operations = _load("operations.json")
    op_id = _gen_id("op")
    op_row = {
        "id": op_id,
        "workspace_id": workspace["id"],
        "tool_name": "plot_vector_field",
        "status": "queued",
        "requested_at": now,
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "name": None,
        "name_a": None,
        "name_b": None,
        "shape": None,
        "values": None,
        "scale_factor": None,
        "in_place": None,
        "new_basis": None,
        "new_vector": None,
        "f_str": f_str,
        "expr_str": None,
        "point": None,
        "is_vector": None,
        "u": None,
        "unit": None,
        "bounds_raw": bounds if bounds is not None else str([-1, 1, -1, 1, -1, 1]),
        "n": n if n is not None else 10,
        "xlim": None,
        "ylim": None,
        "grid_raw": None,
        "output_kind": "plot",
        "result_tensor_id": None,
        "result_payload": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    operations.append(op_row)
    _save("operations.json", operations)

    # Rate limit before running
    counters = _load("workspace_usage_counters.json")
    dt = datetime.datetime.utcnow()
    bucket = _minute_bucket_start(dt)
    ctr = _get_or_init_counter(counters, workspace["id"], bucket, 60)

    limit = int(workspace.get("ops_per_minute_limit", 0) or 0)
    if limit > 0 and int(ctr.get("ops_requested", 0) or 0) + 1 > limit:
        # Mark op failed; do not increment ops_requested on reject per business rule ("increment ... and reject if would exceed")
        # We'll increment then reject to match rule wording.
        ctr["ops_requested"] = int(ctr.get("ops_requested", 0) or 0) + 1
        ctr["updated_at"] = _now()
        _save("workspace_usage_counters.json", counters)

        # Transition queued -> running is not allowed; fail in queued? Real rule says reject before starting.
        for r in operations:
            if r.get("id") == op_id:
                r["status"] = "failed"
                r["started_at"] = None
                r["finished_at"] = _now()
                r["duration_ms"] = int((time.time() - t0) * 1000)
                r["error_message"] = "Rate limit exceeded"
                r["updated_at"] = _now()
                break
        _save("operations.json", operations)
        # Count as failed
        ctr = _get_or_init_counter(counters, workspace["id"], bucket, 60)
        ctr["ops_failed"] = int(ctr.get("ops_failed", 0) or 0) + 1
        ctr["updated_at"] = _now()
        _save("workspace_usage_counters.json", counters)
        return _err("RATE_LIMIT", "Workspace ops_per_minute_limit exceeded", limit=limit)

    # Increment ops_requested
    ctr["ops_requested"] = int(ctr.get("ops_requested", 0) or 0) + 1
    ctr["updated_at"] = _now()
    _save("workspace_usage_counters.json", counters)

    # Transition to running
    now2 = _now()
    for r in operations:
        if r.get("id") == op_id:
            # queued -> running allowed
            r["status"] = "running"
            r["started_at"] = now2
            r["updated_at"] = now2
            break
    _save("operations.json", operations)

    # Validate inputs
    try:
        if not isinstance(f_str, str):
            raise ValueError("f_str must be a string")
        if n is None:
            n_val = 10
        else:
            n_val = n
        if not isinstance(n_val, int) or n_val <= 0:
            raise ValueError("n must be a positive integer")

        bounds_raw = bounds if bounds is not None else str([-1, 1, -1, 1, -1, 1])
        if isinstance(bounds_raw, str):
            try:
                b = ast.literal_eval(bounds_raw)
            except Exception:
                raise ValueError("bounds must be six numeric values (xmin,xmax,ymin,ymax,zmin,zmax)")
        else:
            # tool schema says bounds is string, but accept list/tuple as input
            b = bounds_raw

        if not isinstance(b, (list, tuple)) or len(b) != 6:
            raise ValueError("bounds must be six numeric values (xmin,xmax,ymin,ymax,zmin,zmax)")
        bb = []
        for v in b:
            if not isinstance(v, (int, float)) or isinstance(v, bool):
                raise ValueError("bounds must be six numeric values (xmin,xmax,ymin,ymax,zmin,zmax)")
            bb.append(float(v))
        xmin, xmax, ymin, ymax, zmin, zmax = bb
        if not (xmin < xmax and ymin < ymax and zmin < zmax):
            raise ValueError("bounds must satisfy min<max for each axis")

        ok, comps_or_msg = _validate_vector_expr(f_str)
        if not ok:
            raise ValueError(comps_or_msg)
        comps = comps_or_msg

        # "Render" metadata only
        fig_id = _gen_id("fig")
        digest = hashlib.sha256((str(comps) + "|" + str(bb) + "|" + str(n_val)).encode("utf-8")).hexdigest()
        payload = {
            "backend": "matplotlib",
            "figure_id": fig_id,
            "kind": "vector_field_3d",
            "f_components": comps,
            "bounds": [xmin, xmax, ymin, ymax, zmin, zmax],
            "n": n_val,
            "request_hash": digest,
        }

        # Succeed operation
        finished = _now()
        dur = int((time.time() - t0) * 1000)
        for r in operations:
            if r.get("id") == op_id:
                r["status"] = "succeeded"
                r["finished_at"] = finished
                r["duration_ms"] = dur
                r["result_payload"] = payload
                r["updated_at"] = finished
                break
        _save("operations.json", operations)

        # Increment succeeded
        counters = _load("workspace_usage_counters.json")
        ctr = _get_or_init_counter(counters, workspace["id"], bucket, 60)
        ctr["ops_succeeded"] = int(ctr.get("ops_succeeded", 0) or 0) + 1
        ctr["updated_at"] = _now()
        _save("workspace_usage_counters.json", counters)

        return {
            "operation": {"id": op_id, "status": "succeeded", "output_kind": "plot"},
            "plot": payload,
        }
    except ValueError as ve:
        # Fail operation
        finished = _now()
        dur = int((time.time() - t0) * 1000)
        for r in operations:
            if r.get("id") == op_id:
                r["status"] = "failed"
                r["finished_at"] = finished
                r["duration_ms"] = dur
                r["error_message"] = str(ve)
                r["updated_at"] = finished
                break
        _save("operations.json", operations)

        counters = _load("workspace_usage_counters.json")
        ctr = _get_or_init_counter(counters, workspace["id"], bucket, 60)
        ctr["ops_failed"] = int(ctr.get("ops_failed", 0) or 0) + 1
        ctr["updated_at"] = _now()
        _save("workspace_usage_counters.json", counters)

        return _err("VALIDATION_ERROR", str(ve), operation_id=op_id)
    except Exception:
        finished = _now()
        dur = int((time.time() - t0) * 1000)
        for r in operations:
            if r.get("id") == op_id:
                r["status"] = "failed"
                r["finished_at"] = finished
                r["duration_ms"] = dur
                r["error_message"] = "Internal error"
                r["updated_at"] = finished
                break
        _save("operations.json", operations)

        counters = _load("workspace_usage_counters.json")
        ctr = _get_or_init_counter(counters, workspace["id"], bucket, 60)
        ctr["ops_failed"] = int(ctr.get("ops_failed", 0) or 0) + 1
        ctr["updated_at"] = _now()
        _save("workspace_usage_counters.json", counters)

        return _err("CONFLICT", "Internal error", operation_id=op_id)

def list_tensors(status=None, name_prefix=None, include_values=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, base64, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0398000" if __import__("os").path.isdir("./environment_mix/0398000") else "/app/database")

    def _load(nm):
        try:
            with open(os.path.join(_DB, nm), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(nm, d):
        with open(os.path.join(_DB, nm), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _select_authorized_workspace():
        for w in _load("workspaces.json"):
            if w.get("status") == "active":
                return w
        return None

    def _decode_cursor(cur):
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8")

    def _key(v):
        # Ensure stable sorting even with missing fields
        return v if v is not None else ""

    t0 = time.time()
    workspace = _select_authorized_workspace()
    if not workspace:
        return _err("UNAUTHORIZED", "No active workspace is available for this operation")

    # Defaults
    if include_values is None:
        include_values = False
    if limit is None:
        limit = 50
    if sort is None:
        sort = "updated_at"
    if order is None:
        order = "desc"

    # Validate inputs
    if status is not None and status not in ("active", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status filter")
    if name_prefix is not None:
        if not isinstance(name_prefix, str) or len(name_prefix) < 1:
            return _err("VALIDATION_ERROR", "name_prefix must be a non-empty string")
    if not isinstance(include_values, bool):
        return _err("VALIDATION_ERROR", "include_values must be a boolean")
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if sort not in ("created_at", "updated_at", "name"):
        return _err("VALIDATION_ERROR", "Invalid sort key")
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Invalid order")
    if cursor is not None and (not isinstance(cursor, str) or not cursor):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")

    # Record operation dynamics as an operations row (read tool not in enum; store as failed? better: do not create operations row).
    # Schema mandates operations.tool_name enum without list_tensors/get_tensor, so we only meter usage counters for calls.
    counters = _load("workspace_usage_counters.json")
    dt = datetime.datetime.utcnow()
    bucket = dt.replace(second=0, microsecond=0)
    bucket_iso = bucket.replace(microsecond=0).isoformat() + "Z"
    # get/init counter
    ctr = None
    for r in counters:
        if r.get("workspace_id") == workspace["id"] and r.get("window_start") == bucket_iso and int(r.get("window_seconds", 0) or 0) == 60:
            ctr = r
            break
    if ctr is None:
        ctr = {
            "id": f"wuc_{int(time.time()*1000)}",
            "workspace_id": workspace["id"],
            "window_start": bucket_iso,
            "window_seconds": 60,
            "ops_requested": 0,
            "ops_succeeded": 0,
            "ops_failed": 0,
            "tensor_bytes_written": 0,
            "created_at": _now(),
            "updated_at": _now(),
        }
        counters.append(ctr)

    # list is not a compute op; do not rate-limit against ops_per_minute_limit (rule says "before starting an operation")
    ctr["updated_at"] = _now()
    _save("workspace_usage_counters.json", counters)

    tensors = _load("tensors.json")

    # Filter by workspace + active workspace only
    items = [t for t in tensors if t.get("workspace_id") == workspace["id"]]

    if status is not None:
        items = [t for t in items if t.get("status") == status]
    if name_prefix is not None:
        items = [t for t in items if isinstance(t.get("name"), str) and t.get("name").startswith(name_prefix)]

    total = len(items)

    reverse = (order == "desc")
    if sort in ("created_at", "updated_at"):
        items.sort(key=lambda t: _key(t.get(sort)), reverse=reverse)
    else:
        items.sort(key=lambda t: _key(t.get("name")), reverse=reverse)

    start = 0
    if cursor is not None:
        cobj = _decode_cursor(cursor)
        if not cobj or cobj.get("workspace_id") != workspace["id"]:
            return _err("VALIDATION_ERROR", "Invalid cursor")
        if cobj.get("sort") != sort or cobj.get("order") != order or cobj.get("status") != status or cobj.get("name_prefix") != name_prefix:
            return _err("VALIDATION_ERROR", "Cursor does not match current query parameters")
        start = int(cobj.get("offset", 0) or 0)
        if start < 0 or start > total:
            return _err("VALIDATION_ERROR", "Invalid cursor offset")

    page = items[start:start + limit]
    next_offset = start + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor({
        "workspace_id": workspace["id"],
        "sort": sort,
        "order": order,
        "status": status,
        "name_prefix": name_prefix,
        "offset": next_offset,
    }) if has_more else None

    # If include_values, include but refuse if payload too large (use workspace max_tensor_bytes as per-tensor; for list, refuse if sum too big)
    ws_max = int(workspace.get("max_tensor_bytes", 0) or 0)
    if include_values:
        # Rough bound: if any tensor bytes_size exceeds max, it's already stored; but list response could be large: cap at 2*max per response
        cap = max(1024 * 1024, 2 * ws_max) if ws_max > 0 else 1024 * 1024
        s = 0
        for t in page:
            s += int(t.get("bytes_size", 0) or 0)
            if s > cap:
                return _err("QUOTA_EXCEEDED", "Requested values payload is too large for a single response", cap_bytes=cap)

    def _public_tensor(t):
        out = {
            "id": t.get("id"),
            "workspace_id": t.get("workspace_id"),
            "name": t.get("name"),
            "status": t.get("status"),
            "dtype": t.get("dtype"),
            "rank": t.get("rank"),
            "shape": t.get("shape"),
            "element_count": t.get("element_count"),
            "content_hash": t.get("content_hash"),
            "bytes_size": t.get("bytes_size"),
            "origin_operation_id": t.get("origin_operation_id"),
            "deleted_at": t.get("deleted_at"),
            "created_at": t.get("created_at"),
            "updated_at": t.get("updated_at"),
        }
        if include_values:
            out["values"] = t.get("values")
        return out

    return {
        "data": [_public_tensor(t) for t in page],
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
        },
        "latency_ms": int((time.time() - t0) * 1000),
    }

def list_operations(status=None, tool_name=None, since=None, until=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0398000" if __import__("os").path.isdir("./environment_mix/0398000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    t0 = time.time()
    endpoint = "list_operations"

    # Validate inputs
    valid_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    valid_sort = {"requested_at", "created_at", "updated_at"}
    valid_order = {"asc", "desc"}

    if status is not None and (not isinstance(status, str) or status not in valid_status):
        return _err("VALIDATION_ERROR", "Invalid 'status'.", field="status")
    if tool_name is not None and (not isinstance(tool_name, str) or len(tool_name) < 1):
        return _err("VALIDATION_ERROR", "Invalid 'tool_name'.", field="tool_name")

    since_dt = _parse_rfc3339(since)
    if since is not None and since_dt is None:
        return _err("VALIDATION_ERROR", "Invalid 'since' timestamp; must be RFC3339.", field="since")
    until_dt = _parse_rfc3339(until)
    if until is not None and until_dt is None:
        return _err("VALIDATION_ERROR", "Invalid 'until' timestamp; must be RFC3339.", field="until")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "Invalid 'limit'; must be integer in [1, 200].", field="limit")

    if sort is None:
        sort = "requested_at"
    if not isinstance(sort, str) or sort not in valid_sort:
        return _err("VALIDATION_ERROR", "Invalid 'sort'.", field="sort")

    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in valid_order:
        return _err("VALIDATION_ERROR", "Invalid 'order'.", field="order")

    decoded = None
    if cursor is not None:
        decoded = _decode_cursor(cursor)
        if decoded is None or not isinstance(decoded, dict):
            return _err("VALIDATION_ERROR", "Invalid 'cursor'.", field="cursor")
        # enforce same query shape (best-effort)
        for k in ("status", "tool_name", "since", "until", "sort", "order"):
            if decoded.get(k) != {"status": status, "tool_name": tool_name, "since": since, "until": until, "sort": sort, "order": order}.get(k):
                return _err("VALIDATION_ERROR", "Cursor does not match current query parameters.", field="cursor")

    workspaces = _load("workspaces.json")
    ops = _load("operations.json")
    counters = _load("workspace_usage_counters.json")

    # Ambient auth resolution: choose any active workspace (no explicit credential in tool surface)
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("status") == "active":
            ws = w
            break
    if ws is None:
        # log call (no workspace context)
        status_code = "UNAUTHORIZED"
        latency_ms = int((time.time() - t0) * 1000)
        # No request log collection in schema; record into operations as an audit-like entry is NOT allowed (would fabricate).
        return _err("UNAUTHORIZED", "No accessible active workspace context.")

    ws_id = ws.get("id")
    if not isinstance(ws_id, str) or not ws_id:
        return _err("UNAUTHORIZED", "No accessible active workspace context.")

    # Rate limiting via workspace_usage_counters (ops_per_minute_limit; reads count as ops_requested)
    limit_per_min = ws.get("ops_per_minute_limit")
    if not isinstance(limit_per_min, int) or limit_per_min < 0:
        return _err("VALIDATION_ERROR", "Workspace misconfigured ops_per_minute_limit.")
    now = datetime.datetime.now(datetime.timezone.utc)
    window_start = now.replace(second=0, microsecond=0)
    window_start_iso = window_start.isoformat().replace("+00:00", "Z")

    def _find_counter():
        for c in counters:
            if not isinstance(c, dict):
                continue
            if c.get("workspace_id") == ws_id and c.get("window_seconds") == 60 and c.get("window_start") == window_start_iso:
                return c
        return None

    ctr = _find_counter()
    if ctr is None:
        ctr = {
            "id": f"wuc_{ws_id}_{int(window_start.timestamp())}",
            "workspace_id": ws_id,
            "window_start": window_start_iso,
            "window_seconds": 60,
            "ops_requested": 0,
            "ops_succeeded": 0,
            "ops_failed": 0,
            "tensor_bytes_written": 0,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        counters.append(ctr)

    if not isinstance(ctr.get("ops_requested"), int) or ctr["ops_requested"] < 0:
        ctr["ops_requested"] = 0

    if isinstance(limit_per_min, int) and limit_per_min != 0 and (ctr["ops_requested"] + 1) > limit_per_min:
        ctr["updated_at"] = _now_iso()
        _save("workspace_usage_counters.json", counters)
        return _err("RATE_LIMIT", "Workspace operations per minute limit exceeded.", limit=limit_per_min, window_seconds=60, window_start=window_start_iso)

    ctr["ops_requested"] += 1
    ctr["updated_at"] = _now_iso()
    _save("workspace_usage_counters.json", counters)

    # Filter operations by workspace and optional filters
    rows = []
    for op in ops:
        if not isinstance(op, dict):
            continue
        if op.get("workspace_id") != ws_id:
            continue
        # Only operations in active workspace are considered accessible
        if status is not None and op.get("status") != status:
            continue
        if tool_name is not None and op.get("tool_name") != tool_name:
            continue
        req_at = op.get("requested_at")
        req_dt = _parse_rfc3339(req_at) if isinstance(req_at, str) else None
        if since_dt is not None:
            if req_dt is None or req_dt < since_dt:
                continue
        if until_dt is not None:
            if req_dt is None or req_dt >= until_dt:
                continue
        rows.append(op)

    # Sort
    def _key(o):
        v = o.get(sort)
        dt = _parse_rfc3339(v) if isinstance(v, str) else None
        if dt is None:
            # Put missing timestamps at the end for asc, beginning for desc by using epoch/min
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return dt

    reverse = (order == "desc")
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)

    # Apply cursor (offset-based with stable id tie-break)
    start = 0
    if decoded is not None:
        start = decoded.get("offset", 0)
        if not isinstance(start, int) or start < 0:
            return _err("VALIDATION_ERROR", "Invalid cursor offset.", field="cursor")
        if start > total:
            start = total

    page = rows[start:start + limit]
    next_offset = start + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor({"status": status, "tool_name": tool_name, "since": since, "until": until, "sort": sort, "order": order, "offset": next_offset}) if has_more else None

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "operations": page,
        "meta": {
            "workspace_id": ws_id,
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order,
            "latency_ms": latency_ms,
        },
    }

def get_operation(id, include_payload=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0398000" if __import__("os").path.isdir("./environment_mix/0398000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_dt.isoformat().replace("+00:00", "Z")

    if include_payload is None:
        include_payload = True
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "Invalid 'id'.", field="id")
    if not isinstance(include_payload, bool):
        return _err("VALIDATION_ERROR", "Invalid 'include_payload'.", field="include_payload")

    workspaces = _load("workspaces.json")
    operations = _load("operations.json")
    counters = _load("workspace_usage_counters.json")

    op = next((o for o in operations if isinstance(o, dict) and o.get("id") == id), None)
    if not op:
        # must not fail due to wrong context selection; but NOT_FOUND is correct when no such id exists
        # still record metering if possible
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("status") == "active"), None)
        if ws and isinstance(ws.get("id"), str):
            ws_id = ws["id"]
            bucket = now_dt.astimezone(datetime.timezone.utc).replace(second=0, microsecond=0).isoformat().replace("+00:00", "Z")
            crow = next((c for c in counters if isinstance(c, dict) and c.get("workspace_id") == ws_id and c.get("window_start") == bucket and int(c.get("window_seconds") or 0) == 60), None)
            if not crow:
                crow = {"id": f"sci_wuc_read_{int(time.time()*1000)}", "workspace_id": ws_id, "window_start": bucket, "window_seconds": 60,
                        "ops_requested": 0, "ops_succeeded": 0, "ops_failed": 0, "tensor_bytes_written": 0, "created_at": now_iso, "updated_at": now_iso}
                counters.append(crow)
            crow["ops_requested"] = int(crow.get("ops_requested") or 0) + 1
            crow["ops_failed"] = int(crow.get("ops_failed") or 0) + 1
            crow["updated_at"] = now_iso
            _save("workspace_usage_counters.json", counters)
        return _err("NOT_FOUND", "Operation not found.", id=id)

    ws_id = op.get("workspace_id")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
    if not ws or ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Operation is not accessible (workspace inactive or missing).", id=id, workspace_id=ws_id)

    # Meter (counts as operation request)
    bucket = now_dt.astimezone(datetime.timezone.utc).replace(second=0, microsecond=0).isoformat().replace("+00:00", "Z")
    crow = next((c for c in counters if isinstance(c, dict) and c.get("workspace_id") == ws_id and c.get("window_start") == bucket and int(c.get("window_seconds") or 0) == 60), None)
    if not crow:
        crow = {"id": f"sci_wuc_read_{int(time.time()*1000)}", "workspace_id": ws_id, "window_start": bucket, "window_seconds": 60,
                "ops_requested": 0, "ops_succeeded": 0, "ops_failed": 0, "tensor_bytes_written": 0, "created_at": now_iso, "updated_at": now_iso}
        counters.append(crow)

    ops_limit = int(ws.get("ops_per_minute_limit") or 0)
    proposed = int(crow.get("ops_requested") or 0) + 1
    if ops_limit != 0 and proposed > ops_limit:
        crow["ops_requested"] = proposed
        crow["ops_failed"] = int(crow.get("ops_failed") or 0) + 1
        crow["updated_at"] = now_iso
        _save("workspace_usage_counters.json", counters)
        return _err("RATE_LIMIT", "Workspace rate limit exceeded.", ops_per_minute_limit=ops_limit, window_start=bucket, ops_requested=proposed, workspace_id=ws_id)

    crow["ops_requested"] = proposed
    if op.get("status") == "succeeded":
        crow["ops_succeeded"] = int(crow.get("ops_succeeded") or 0) + 1
    elif op.get("status") in ("failed", "cancelled"):
        crow["ops_failed"] = int(crow.get("ops_failed") or 0) + 1
    crow["updated_at"] = now_iso
    _save("workspace_usage_counters.json", counters)

    # Build response
    base = {k: op.get(k) for k in op.keys()}
    if not include_payload:
        base.pop("result_payload", None)
        # also drop recorded request fields that can be large/noisy
        for k in ("values", "shape", "new_basis", "new_vector", "f_str", "expr_str", "bounds_raw", "grid_raw", "xlim", "ylim", "point", "u"):
            base.pop(k, None)
    base["fetched_at"] = now_iso
    base["latency_ms"] = max(0, int(round((time.time() - t0) * 1000)))
    return {"operation": base}

def cancel_operation(id, reason=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0398000" if __import__("os").path.isdir("./environment_mix/0398000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_dt.isoformat().replace("+00:00", "Z")

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "Invalid 'id'.", field="id")
    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "Invalid 'reason'.", field="reason")
    if isinstance(reason, str):
        reason = reason.strip() or None

    workspaces = _load("workspaces.json")
    operations = _load("operations.json")
    counters = _load("workspace_usage_counters.json")

    op_idx = next((i for i, o in enumerate(operations) if isinstance(o, dict) and o.get("id") == id), None)
    if op_idx is None:
        return _err("NOT_FOUND", "Operation not found.", id=id)

    op = operations[op_idx]
    ws_id = op.get("workspace_id")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
    if not ws or ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Operation is not accessible (workspace inactive or missing).", id=id, workspace_id=ws_id)

    def _minute_bucket_iso(dt):
        dt = dt.astimezone(datetime.timezone.utc).replace(second=0, microsecond=0)
        return dt.isoformat().replace("+00:00", "Z")

    def _ensure_counter_row(bucket_iso):
        for i, r in enumerate(counters):
            if isinstance(r, dict) and r.get("workspace_id") == ws_id and r.get("window_start") == bucket_iso and int(r.get("window_seconds") or 0) == 60:
                return i
        counters.append({
            "id": f"sci_wuc_cancel_{int(time.time()*1000)}",
            "workspace_id": ws_id,
            "window_start": bucket_iso,
            "window_seconds": 60,
            "ops_requested": 0,
            "ops_succeeded": 0,
            "ops_failed": 0,
            "tensor_bytes_written": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        return len(counters) - 1

    def _transition_allowed(cur, nxt):
        g = {
            "queued": {"running", "cancelled"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set(),
        }
        return cur in g and nxt in g[cur]

    # Rate limit accounting for this mutation
    bucket_iso = _minute_bucket_iso(now_dt)
    cidx = _ensure_counter_row(bucket_iso)
    ops_limit = int(ws.get("ops_per_minute_limit") or 0)
    proposed = int(counters[cidx].get("ops_requested") or 0) + 1
    if ops_limit != 0 and proposed > ops_limit:
        counters[cidx]["ops_requested"] = proposed
        counters[cidx]["ops_failed"] = int(counters[cidx].get("ops_failed") or 0) + 1
        counters[cidx]["updated_at"] = now_iso
        _save("workspace_usage_counters.json", counters)
        return _err("RATE_LIMIT", "Workspace rate limit exceeded.", ops_per_minute_limit=ops_limit, window_start=bucket_iso, ops_requested=proposed, workspace_id=ws_id)

    counters[cidx]["ops_requested"] = proposed
    counters[cidx]["updated_at"] = now_iso

    cur = op.get("status")
    if cur not in ("queued", "running"):
        # vendor text says FAILED_PRECONDITION; our allowed codes set doesn't include it, so use INVALID_TRANSITION
        counters[cidx]["ops_failed"] = int(counters[cidx].get("ops_failed") or 0) + 1
        counters[cidx]["updated_at"] = now_iso
        _save("workspace_usage_counters.json", counters)
        return _err("INVALID_TRANSITION", "Operation cannot be cancelled from its current status.", id=id, status=cur)

    if not _transition_allowed(cur, "cancelled"):
        counters[cidx]["ops_failed"] = int(counters[cidx].get("ops_failed") or 0) + 1
        counters[cidx]["updated_at"] = now_iso
        _save("workspace_usage_counters.json", counters)
        return _err("INVALID_TRANSITION", "Invalid operation status transition.", from_status=cur, to_status="cancelled", id=id)

    # Apply mutation
    op["status"] = "cancelled"
    if not op.get("started_at"):
        op["started_at"] = op.get("requested_at") or now_iso
    op["finished_at"] = now_iso
    op["duration_ms"] = max(0, int(round((time.time() - t0) * 1000)))
    if reason:
        # store in error_message for auditing (schema has no dedicated field)
        prev = op.get("error_message")
        op["error_message"] = (prev + " | " if prev else "") + f"Cancelled: {reason}"
    else:
        prev = op.get("error_message")
        if not prev:
            op["error_message"] = "Cancelled."
    op["updated_at"] = now_iso

    counters[cidx]["ops_succeeded"] = int(counters[cidx].get("ops_succeeded") or 0) + 1
    counters[cidx]["updated_at"] = now_iso

    _save("operations.json", operations)
    _save("workspace_usage_counters.json", counters)

    return {"operation": {"id": op.get("id"), "status": op.get("status"), "updated_at": op.get("updated_at"), "error_message": op.get("error_message")}}
